class AppLanguage(enum.Enum):
    """
    Strongly-typed application language identifier.
    """

    EN = 0
    
    ZH_HANS = 1
    
    ZH_HANT = 2
    
    JA = 3
    
    DE = 4
    
    FR = 5
    
    ES = 6
    


class _UniffiConverterTypeAppLanguage(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return AppLanguage.EN
        if variant == 2:
            return AppLanguage.ZH_HANS
        if variant == 3:
            return AppLanguage.ZH_HANT
        if variant == 4:
            return AppLanguage.JA
        if variant == 5:
            return AppLanguage.DE
        if variant == 6:
            return AppLanguage.FR
        if variant == 7:
            return AppLanguage.ES
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == AppLanguage.EN:
            return
        if value == AppLanguage.ZH_HANS:
            return
        if value == AppLanguage.ZH_HANT:
            return
        if value == AppLanguage.JA:
            return
        if value == AppLanguage.DE:
            return
        if value == AppLanguage.FR:
            return
        if value == AppLanguage.ES:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == AppLanguage.EN:
            buf.write_i32(1)
        if value == AppLanguage.ZH_HANS:
            buf.write_i32(2)
        if value == AppLanguage.ZH_HANT:
            buf.write_i32(3)
        if value == AppLanguage.JA:
            buf.write_i32(4)
        if value == AppLanguage.DE:
            buf.write_i32(5)
        if value == AppLanguage.FR:
            buf.write_i32(6)
        if value == AppLanguage.ES:
            buf.write_i32(7)







